//! A from-scratch, dependency-free port of the earcut polygon triangulation
//! algorithm.
//!
//! Input is a polygon given as a list of rings — the first ring is the outer
//! contour, any remaining rings are holes. Output is a flat list of triangle
//! vertex indices into the concatenated ring coordinates.

pub mod geom;
pub mod node;
pub mod triangulate;
pub mod zorder;

pub use self::triangulate::Earcut;

/// Triangulates `polygon` and returns the triangle index list.
pub fn earcut<R: AsRef<[[f64; 2]]>>(polygon: &[R]) -> Vec<u32> {
    let mut ec = Earcut::new();
    ec.run(polygon);
    ec.indices
}

